#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 2);
const uint8_t duties[4] = {0, 85, 170, 255};
int previousGear = -1;
unsigned long lastSample = 0;
bool sampled = false;

int selectGear(float temperatureC) {
  if (temperatureC < 25.0f) return 0;
  if (temperatureC < 30.0f) return 1;
  if (temperatureC < 35.0f) return 2;
  return 3;
}

void setup() {
  pinMode(A1, INPUT);
  pinMode(5, OUTPUT);
  pinMode(6, OUTPUT);
  analogWrite(5, 0);
  noTone(6);
  display.setBrightness(5);
  display.clear();
}

void loop() {
  unsigned long now = millis();
  if (sampled && (unsigned long)(now - lastSample) < 100UL) return;
  sampled = true;
  lastSample = now;
  float temperatureC = analogRead(A1) * (500.0f / 1023.0f);
  int gear = selectGear(temperatureC);
  if (gear != previousGear) {
    analogWrite(5, duties[gear]);
    display.showNumberDec(gear, false);
    if (gear == 3) tone(6, 2000, 150);
    previousGear = gear;
  }
}
